import os,re,subprocess,json,ast
patterns=[rb'(?:AKIA|ASIA)[A-Z0-9]{16}',rb'gh[pousr]_[A-Za-z0-9]{20,}',rb'github_pat_[A-Za-z0-9_]{20,}',rb'hf_[A-Za-z0-9]{20,}',rb'sk-[A-Za-z0-9_-]{20,}',rb'AIza[A-Za-z0-9_-]{30,}',rb'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----',rb'D4w8z9wKN1aVeT3BpQj6kIuN7wH8X0M9KfV5OqzF']
p=re.compile(b'|'.join(patterns));hits=[]; count=0
for root,ds,fs in os.walk('.'):
 ds[:]=[d for d in ds if d!='.git']
 for f in fs:
  path=os.path.join(root,f)
  b=open(path,'rb').read();count+=1
  if p.search(b):hits.append(path)
print('Working-tree files scanned:',count,'; remaining credential-pattern matches:',len(hits))
for h in hits:print(h)
assert not hits
changed=subprocess.check_output(['git','diff','--name-only']).decode().splitlines()
for path in changed:
 if path.endswith('.json'):json.load(open(path))
 if path.endswith('.py'):ast.parse(open(path).read())
print('Changed JSON and Python syntax valid.')
# Check reachable history without printing credentials.
objects=subprocess.check_output(['git','rev-list','--objects','--all']).splitlines();found=[]
for line in objects:
 oid=line.split(b' ',1)[0]
 kind=subprocess.check_output(['git','cat-file','-t',oid]).strip()
 if kind==b'blob' and p.search(subprocess.check_output(['git','cat-file','blob',oid])):found.append(line.split(b' ',1)[-1].decode(errors='replace'))
print('Reachable historical blobs containing credential patterns:',len(found))
for path in found:print(path)
